// pybytes.mjs — Python 3 repr() of a bytes object.

/**
 * Return exactly what Python 3's repr() of a bytes object produces
 * (i.e. what print(b'...') outputs) for the given Buffer.
 *
 * @param {Buffer} buf
 * @returns {string}
 */
export function pyBytesRepr(buf) {
  // Quote selection: single quotes unless the data contains a single
  // quote and no double quote, in which case double quotes are used.
  let hasSingle = false;
  let hasDouble = false;
  for (const byte of buf) {
    if (byte === 0x27) hasSingle = true;
    else if (byte === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  let out = "b" + quoteChar;
  for (const byte of buf) {
    if (byte === 0x5c) {
      out += "\\\\";
    } else if (byte === quote) {
      out += "\\" + quoteChar;
    } else if (byte === 0x09) {
      out += "\\t";
    } else if (byte === 0x0a) {
      out += "\\n";
    } else if (byte === 0x0d) {
      out += "\\r";
    } else if (byte >= 0x20 && byte <= 0x7e) {
      out += String.fromCharCode(byte);
    } else {
      out += "\\x" + byte.toString(16).padStart(2, "0");
    }
  }
  out += quoteChar;
  return out;
}

