export class ConstructError extends Error {}

export const Int8ul = {
  build(value) {
    if (!Number.isInteger(value) || value < 0 || value > 255) {
      throw new ConstructError(`struct '<B' error during building, given value ${value}`);
    }
    const buf = Buffer.alloc(1);
    buf.writeUInt8(value, 0);
    return buf;
  },
};

export const Int16ul = {
  build(value) {
    if (!Number.isInteger(value) || value < 0 || value > 65535) {
      throw new ConstructError(`struct '<H' error during building, given value ${value}`);
    }
    const buf = Buffer.alloc(2);
    buf.writeUInt16LE(value, 0);
    return buf;
  },
};

export function Bytes(n) {
  return {
    build(buf) {
      if (buf.length !== n) {
        throw new ConstructError(`bytes object of wrong length, expected ${n}, found ${buf.length}`);
      }
      return buf;
    },
  };
}

