node --input-type=module -e "
import { ConstructError, Int8ul, Int16ul, Bytes } from '/output/lib/construct.mjs';

const assert = (cond, msg) => { if (!cond) throw new Error('FAIL: ' + msg); };

// Int8ul happy path
let b = Int8ul.build(0); assert(Buffer.isBuffer(b) && b.length === 1 && b[0] === 0, 'Int8ul 0');
b = Int8ul.build(255); assert(b[0] === 255, 'Int8ul 255');
assert(Int8ul.build(65).toString('latin1') === 'A', 'Int8ul 65');

// Int8ul errors
for (const v of [-1, 256, 1.5, 'x', NaN]) {
  try { Int8ul.build(v); throw new Error('no throw for ' + v); }
  catch (e) {
    assert(e instanceof ConstructError, 'ConstructError type');
    assert(e.message === \`struct '<B' error during building, given value \${v}\`, 'msg: ' + e.message);
  }
}

// Int16ul happy path
b = Int16ul.build(0); assert(b.length === 2 && b[0] === 0 && b[1] === 0, 'Int16ul 0');
b = Int16ul.build(0x1234); assert(b[0] === 0x34 && b[1] === 0x12, 'Int16ul LE');
b = Int16ul.build(65535); assert(b[0] === 0xff && b[1] === 0xff, 'Int16ul 65535');

// Int16ul errors
for (const v of [-1, 65536, 2.5, 'x']) {
  try { Int16ul.build(v); throw new Error('no throw for ' + v); }
  catch (e) {
    assert(e instanceof ConstructError, 'ConstructError type');
    assert(e.message === \`struct '<H' error during building, given value \${v}\`, 'msg: ' + e.message);
  }
}

// Bytes
const data = Buffer.from([1, 2, 3]);
assert(Bytes(3).build(data) === data, 'Bytes passthrough');
assert(Bytes(0).build(Buffer.alloc(0)).length === 0, 'Bytes(0)');
try { Bytes(4).build(data); throw new Error('no throw'); }
catch (e) {
  assert(e instanceof ConstructError, 'Bytes ConstructError');
  assert(e.message === 'bytes object of wrong length, expected 4, found 3', 'msg: ' + e.message);
}

console.log('ALL TESTS PASSED');
"

