import { basename } from 'node:path';

const OPTIONS = [
  { name: 'a', type: 'int' },
  { name: 'b', type: 'int' },
  { name: 'c', type: 'str' },
  { name: 'd', type: 'int' },
  { name: 'e', type: 'str' },
  { name: 'f', type: 'int' },
  { name: 'g', type: 'int' },
];

function prog() {
  return basename(process.argv[1] || 'test17.mjs');
}

function usageLine() {
  return `usage: ${prog()} [-h] --a A --b B --c C --d D --e E --f F --g G`;
}

function error(message) {
  process.stderr.write(usageLine() + '\n');
  process.stderr.write(`${prog()}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  process.stdout.write(usageLine() + '\n');
  process.stdout.write('\noptions:\n');
  process.stdout.write('  -h, --help  show this help message and exit\n');
  for (const opt of OPTIONS) {
    process.stdout.write(`  --${opt.name} ${opt.name.toUpperCase()}\n`);
  }
  process.exit(0);
}

function parseInt_(raw, optName) {
  if (!/^[-+]?\d+$/.test(raw)) {
    error(`argument --${optName}: invalid int value: '${raw}'`);
  }
  const value = Number(raw);
  if (!Number.isSafeInteger(value)) {
    error(`argument --${optName}: invalid int value: '${raw}'`);
  }
  return value;
}

export function parseArgs(argv) {
  const byName = new Map(OPTIONS.map((o) => [o.name, o]));
  const values = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp();
    }

    if (token.startsWith('--')) {
      let name = token.slice(2);
      let value;
      const eq = name.indexOf('=');
      if (eq !== -1) {
        value = name.slice(eq + 1);
        name = name.slice(0, eq);
      } else if (i + 1 < argv.length) {
        value = argv[++i];
      }

      const opt = byName.get(name);
      if (!opt) {
        extras.push(token);
        if (eq === -1 && value !== undefined) extras.push(value);
        continue;
      }

      if (value === undefined) {
        error(`argument --${name}: expected one argument`);
      }

      values[name] = opt.type === 'int' ? parseInt_(value, name) : value;
    } else {
      extras.push(token);
    }
  }

  const missing = OPTIONS.filter((o) => !(o.name in values)).map((o) => `--${o.name}`);
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

