node -e '
import("/output/lib/pybytes.mjs").then(({ pyBytesRepr }) => {
  const cases = [
    [Buffer.from([79]), "b\x27O\x27"],
    [Buffer.from([107, 212]), "b\x27k\\xd4\x27"],
    [Buffer.from("middle", "utf8"), "b\x27middle\x27"],
    [Buffer.from([186]), "b\x27\\xba\x27"],
    [Buffer.from([232]), "b\x27\\xe8\x27"],
    [Buffer.from([0x27]), "b\"\x27\""],                       // single quote only -> double quotes
    [Buffer.from([0x22]), "b\x27\"\x27"],                    // double quote only -> single quotes
    [Buffer.from([0x27, 0x22]), "b\x27\\\x27\"\x27"],        // both -> single quotes, escape single
    [Buffer.from([0x5c]), "b\x27\\\\\x27"],                  // backslash
    [Buffer.from([0x09, 0x0a, 0x0d]), "b\x27\\t\\n\\r\x27"], // tab/newline/cr
    [Buffer.from([0x00, 0x1f, 0x20, 0x7e, 0x7f, 0xff]), "b\x27\\x00\\x1f ~\\x7f\\xff\x27"],
    [Buffer.from([]), "b\x27\x27"],                          // empty
  ];
  let fail = 0;
  for (const [input, expected] of cases) {
    const got = pyBytesRepr(input);
    if (got !== expected) { fail++; console.log("FAIL", JSON.stringify([...input]), "got", JSON.stringify(got), "want", JSON.stringify(expected)); }
  }
  // exhaustive byte check against expected per-byte rendering
  for (let b = 0; b < 256; b++) {
    let want;
    if (b === 0x5c) want = "\\\\";
    else if (b === 0x27) want = "\\\x27";
    else if (b === 0x09) want = "\\t";
    else if (b === 0x0a) want = "\\n";
    else if (b === 0x0d) want = "\\r";
    else if (b >= 0x20 && b <= 0x7e) want = String.fromCharCode(b);
    else want = "\\x" + b.toString(16).padStart(2, "0");
    const got = pyBytesRepr(Buffer.from([b, 0x27])).slice(2, -1); // force double-quote path off; use single+double? simpler: single byte with a double quote to force single quotes
    const got2 = pyBytesRepr(Buffer.from([b, 0x22])).slice(2, -1);
    const expected = want + "\x22";
    if (got2 !== expected) { fail++; console.log("BYTE FAIL", b, JSON.stringify(got2), JSON.stringify(expected)); }
  }
  console.log(fail === 0 ? "ALL PASS" : fail + " FAILURES");
});
'

