const PROG = 'scratch-runner.mjs';
const USAGE = `usage: ${PROG} [-h] --a A --b B --c C --d D --e E --f F --g G`;
const ALL = ['--a', '1', '--b', '2', '--c', 'hi', '--d', '3', '--e', 'yo', '--f', '4', '--g', '5'];

let pass = 0, fail = 0;
function check(name, cond, detail) {
  if (cond) { pass++; console.log(`PASS ${name}`); }
  else { fail++; console.log(`FAIL ${name}: ${detail}`); }
}

// 1. happy path, space form
let r = run(ALL);
check('happy space form', r.code === 0 && r.out.trim() === JSON.stringify({ a: 1, b: 2, c: 'hi', d: 3, e: 'yo', f: 4, g: 5 }), JSON.stringify(r));

// 2. happy path, = form (mix)
r = run(['--a=1', '--b', '2', '--c=hi', '--d=3', '--e', 'yo', '--f=4', '--g=5']);
check('equals form', r.code === 0 && r.out.trim() === '{"a":1,"b":2,"c":"hi","d":3,"e":"yo","f":4,"g":5}', JSON.stringify(r));

// 3. negative and + ints
r = run(['--a', '-12', '--b=+7', '--c', 'x', '--d', '0', '--e', '', '--f', '9007199254740991', '--g', '-9007199254740991']);
check('neg/plus/limits', r.code === 0 && r.out.includes('"a":-12') && r.out.includes('"b":7') && r.out.includes('"f":9007199254740991') && r.out.includes('"g":-9007199254740991'), JSON.stringify(r));

// 4. invalid int
r = run(['--a', '1.5', '--b', '2', '--c', 'x', '--d', '3', '--e', 'y', '--f', '4', '--g', '5']);
check('invalid int', r.code === 2 && r.err === `${USAGE}\n${PROG}: error: argument --a: invalid int value: '1.5'\n`, JSON.stringify(r));

// 4b. invalid int via = form
r = run(['--a=abc', '--b', '2', '--c', 'x', '--d', '3', '--e', 'y', '--f', '4', '--g', '5']);
check('invalid int = form', r.code === 2 && r.err === `${USAGE}\n${PROG}: error: argument --a: invalid int value: 'abc'\n`, JSON.stringify(r));

// 4c. unsafe integer rejected
r = run(['--a', '9007199254740992', '--b', '2', '--c', 'x', '--d', '3', '--e', 'y', '--f', '4', '--g', '5']);
check('unsafe int rejected', r.code === 2 && r.err === `${USAGE}\n${PROG}: error: argument --a: invalid int value: '9007199254740992'\n`, JSON.stringify(r));

// 5. missing required (single)
r = run(['--a', '1', '--b', '2', '--c', 'x', '--d', '3', '--e', 'y', '--f', '4']);
check('missing --g', r.code === 2 && r.err === `${USAGE}\n${PROG}: error: the following arguments are required: --g\n`, JSON.stringify(r));

// 6. missing required (multiple, declaration order)
r = run(['--b', '2', '--e', 'y']);
check('missing multiple', r.code === 2 && r.err === `${USAGE}\n${PROG}: error: the following arguments are required: --a, --c, --d, --f, --g\n`, JSON.stringify(r));

// 7. unrecognized arguments
r = run([...ALL, '--zzz', '9']);
check('unrecognized', r.code === 2 && r.err === `${USAGE}\n${PROG}: error: unrecognized arguments: --zzz 9\n`, JSON.stringify(r));

// 8. missing required takes precedence over unrecognized
r = run(['--a', '1', '--zzz']);
check('missing beats unrecognized', r.code === 2 && r.err.includes('the following arguments are required'), JSON.stringify(r));

// 9. help
r = run(['--help']);
check('help exit 0 usage', r.code === 0 && r.out.startsWith(USAGE + '\n') && r.out.includes('--a A') && r.out.includes('-h, --help'), JSON.stringify(r));
r = run(['-h']);
check('-h alias', r.code === 0 && r.out.startsWith(USAGE + '\n'), JSON.stringify(r));

// 10. expected one argument
r = run(['--a']);
check('expected one argument', r.code === 2 && r.err.includes("argument --a: expected one argument"), JSON.stringify(r));

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

